/* The new shot owns its own local clock; inserting it never retimes earlier scenes. */
export const depotEase=x=>{x=Math.max(0,Math.min(1,x));return x*x*(3-2*x)};
export function depotState(age,f){const descent=depotEase(age/Math.max(.1,f.depotDescent)),pull=depotEase((age-f.depotPullStart)/Math.max(.1,f.depotPullTime));return {descent,pull,outgoingY:-540*descent,incomingY:540*(1-descent),actorScale:f.depotStartScale+(f.depotEndScale-f.depotStartScale)*pull,backScale:f.depotBackgroundStart+(1-f.depotBackgroundStart)*pull,frontScale:f.depotFrontScale+(1-f.depotFrontScale)*pull,roomBlur:f.depotBlurStart+(f.depotBlurEnd-f.depotBlurStart)*depotEase((age-f.depotDescent)/Math.max(.1,f.depotFocusTime)),smoke:1-depotEase(age/Math.max(.1,f.depotSmokeClear))}}
export function depotPlacement(object,state,f){const depth=object.depth||'people',scale=depth==='front'?state.frontScale:depth==='back'?state.backScale:state.actorScale;return {x:f.depotFocusX+(object.x-f.depotFocusX)*scale,y:f.depotFocusY+(object.y-f.depotFocusY)*scale,scale,rotation:object.rotation||0}}
export function depotEnvelope(age,o){return o.visible===false?0:(o.opacity??1)*depotEase((age-(o.start||0))/Math.max(.1,o.fade||1))}
export function depotPhase(d,f){const overlap=Math.max(0,Math.min(Number(f.depotDescent)||5,Number(f.battleDuration)||26));return {...d,depot:d.images-overlap,images:d.images+Number(f.depotDuration)-overlap,end:d.end+Number(f.depotDuration)-overlap}}
